34	/// @title raffle.fun Raffle Escrow and Entry Ticket
35	/// @author heesho
36	/// @notice Escrows one NFT and sells fixed-price USDC entries through one transferable ERC-721 ticket per purchase.
37	/// @dev Ticket IDs are sequential and map to one inclusive `[firstEntry,lastEntry]` uint128 range. Purchases, Chainlink
38	///      callbacks, and winner proofs are O(1) in entry count. Tickets remain transferable bearer claims until their
39	///      owners burn them for redemption or refund. Each raffle is a fixed, non-upgradeable ERC-1167 clone with no
40	///      administrator or rescue path. Permissionless settlement only allocates liabilities; the winning-ticket owner
41	///      atomically burns the ticket while receiving the NFT or cash prize.
42	/// @custom:version 1.0.0
43	contract Raffle is IRaffle, ERC721, ReentrancyGuard, IERC721Receiver, VRFV2PlusWrapperConsumerBase {
44	    using SafeERC20 for IERC20;
45	
46	    // Types
47	
48	    /// @notice Inclusive global entry-number range represented by one sequential ERC-721 ticket.
49	    /// @param firstEntry First represented one-based global entry.
50	    /// @param lastEntry Last represented one-based global entry.
51	    struct TicketRange {
52	        uint128 firstEntry;
53	        uint128 lastEntry;
54	    }
