223	    /// @inheritdoc IRaffle
224	    function buyEntries(address recipient, uint128 entryCount)
225	        external
226	        override
227	        nonReentrant
228	        returns (uint256 ticketId)
229	    {
230	        _requireStatus(Status.Active);
231	        if (block.timestamp >= endTime) revert SaleEnded(endTime, block.timestamp);
232	        if (recipient == address(0)) revert InvalidRecipient();
233	        if (entryCount == 0) revert ZeroEntryCount();
234	        if (entryCount > type(uint128).max - totalEntries) {
235	            revert TotalEntriesOverflow(totalEntries, entryCount);
236	        }
237	
238	        uint256 grossAmount = uint256(entryCount) * ENTRY_PRICE;
239	        quoteToken.safeTransferFrom(msg.sender, address(this), grossAmount);
240	
241	        uint128 firstEntry = totalEntries + 1;
242	        uint128 lastEntry = totalEntries + entryCount;
243	        ticketId = uint256(ticketCount) + 1;
244	
245	        totalEntries = lastEntry;
246	        ++ticketCount;
247	        _ticketRanges[ticketId] = TicketRange({ firstEntry: firstEntry, lastEntry: lastEntry });
248	        unsettledPot += grossAmount;
249	
250	        _safeMint(recipient, ticketId);
251	        emit TicketPurchased(msg.sender, recipient, ticketId, firstEntry, lastEntry, entryCount, grossAmount);
252	    }
