254	    /// @inheritdoc IRaffle
255	    function requestDraw() external payable override nonReentrant returns (uint256 requestId) {
256	        _requireStatus(Status.Active);
257	        if (block.timestamp < endTime) revert RaffleNotEnded(endTime, block.timestamp);
258	        if (totalEntries == 0) revert NoEntriesSold();
259	        uint256 requestDeadline = drawRequestDeadline();
260	        if (block.timestamp >= requestDeadline) {
261	            revert DrawRequestWindowExpired(requestDeadline, block.timestamp);
262	        }
263	
264	        uint256 quotedFee = getVrfRequestPrice();
265	        if (msg.value < quotedFee) revert InsufficientVrfFee(quotedFee, msg.value);
266	
267	        status = Status.Drawing;
268	        drawRequestedAt = uint64(block.timestamp);
269	        _requestInFlight = true;
270	        bytes memory extraArgs = VRFV2PlusClient._argsToBytes(VRFV2PlusClient.ExtraArgsV1({ nativePayment: true }));
271	        uint256 paidPrice;
272	        (requestId, paidPrice) = requestRandomnessPayInNative(callbackGasLimit, requestConfirmations, 1, extraArgs);
273	        if (paidPrice > msg.value) revert InsufficientVrfFee(paidPrice, msg.value);
274	        vrfRequestId = requestId;
275	        _requestInFlight = false;
276	
277	        uint256 excess = msg.value - paidPrice;
278	        if (excess != 0) {
279	            bool success;
280	            address refundRecipient = msg.sender;
281	            assembly ("memory-safe") {
282	                success := call(gas(), refundRecipient, excess, 0, 0, 0, 0)
283	            }
284	            if (!success) revert NativeRefundFailed(msg.sender, excess);
285	        }
286	
287	        emit DrawRequested(requestId, msg.sender, paidPrice, excess, drawRequestedAt, callbackDeadline());
288	    }
