504	    // Internal state-changing functions
505	
506	    /// @dev Tickets remain transferable bearer claims in every lifecycle state. Known protocol sinks are rejected
507	    ///      before their ownership could make a claim unreachable. Burns pass the zero address and remain permitted.
508	    /// @param to Prospective ticket recipient, or the zero address for a burn.
509	    /// @param ticketId Ticket being minted, transferred, or burned.
510	    /// @param auth Caller whose owner or operator authority is checked by ERC-721.
511	    /// @return previousOwner Ticket owner before the update, or the zero address for a mint.
512	    function _update(address to, uint256 ticketId, address auth) internal override returns (address previousOwner) {
513	        if (to != address(0) && _isProtocolDestination(to, address(prizeToken))) {
514	            revert UnsafeProtocolDestination(to);
515	        }
516	        previousOwner = super._update(to, ticketId, auth);
517	    }
518	
519	    /// @dev Authenticated randomness selects only an entry. No ticket search, loop, user call, or token transfer
520	    ///      occurs. In-flight, late, wrong-request, duplicate, and ABI-decodable wrong-length callbacks are ignored for
521	    ///      liveness; malformed ABI calldata reverts during Solidity decoding before this handler runs.
522	    /// @param requestId Wrapper-authenticated request identifier supplied by the callback.
523	    /// @param randomWords Callback words; exactly one word is required for resolution.
524	    function fulfillRandomWords(uint256 requestId, uint256[] memory randomWords) internal override {
525	        if (
526	            _requestInFlight || status != Status.Drawing || requestId != vrfRequestId || randomWords.length != 1
527	                || block.timestamp >= callbackDeadline()
528	        ) {
529	            emit VrfCallbackIgnored(requestId, vrfRequestId, status);
530	            return;
531	        }
532	
533	        uint128 resolvedEntry = uint128((randomWords[0] % uint256(totalEntries)) + 1);
534	        winningEntry = resolvedEntry;
535	        resolvedAt = uint64(block.timestamp);
536	        status = totalEntries >= reserveEntries ? Status.NftWon : Status.CashWon;
537	
538	        emit RaffleResolved(requestId, resolvedEntry, status);
539	    }
