541	    // Private state-changing helpers
542	
543	    /// @dev Validates the winning range once and allocates all terminal quote-token liabilities without transferring
544	    ///      an asset or reading ticket ownership. Both percentage allocations round down; sponsor proceeds are the
545	    ///      remainder.
546	    /// @param ticketId Ticket whose inclusive range must contain the selected winning entry.
547	    /// @return cashAmount Raw six-decimal quote-token units allocated to the cash winner, or zero for `NftWon`.
548	    function _settleWinningTicket(uint256 ticketId) private returns (uint256 cashAmount) {
549	        if (settlementComplete) revert SettlementAlreadyComplete();
550	        Status result = status;
551	        if (result != Status.NftWon && result != Status.CashWon) revert InvalidStatus(result);
552	
553	        _requireWinningTicket(ticketId);
554	        uint256 grossPot = unsettledPot;
